    <script>
        // ゲーム状態
        const gameState = {
            currentArea: 0, // 0:A-1, 1:A-2, 2:B-1, 3:B-2
            playerPosition: { x: 200, y: 200 },
            enemyPosition: { x: 400, y: 300 },
            isMoving: false,
            activeSensor: 'optical',
            generatorPower: 50,
            aiPower: 50,
            moveSpeed: 30,
            sensorPower: 40,
            detectionStatus: null,
            pendingAreaMove: null
        };

        const areaNames = ['A-1', 'A-2', 'B-1', 'B-2'];
        const areaConnections = {
            0: { north: 1, east: 2 },      // A-1 -> A-2(北), B-1(東)
            1: { south: 0, east: 3 },      // A-2 -> A-1(南), B-2(東)
            2: { north: 3, west: 0 },      // B-1 -> B-2(北), A-1(西)
            3: { south: 2, west: 1 }       // B-2 -> B-1(南), A-2(西)
        };

        // エリア境界チェック
        function checkAreaBoundary() {
            const boundaries = document.querySelectorAll('.area-boundary');
            const playerX = gameState.playerPosition.x;
            const playerY = gameState.playerPosition.y;
            const container = document.querySelector('.current-area');
            const containerRect = container.getBoundingClientRect();

            boundaries.forEach(boundary => {
                boundary.classList.remove('visible');
            });

            // 境界近接チェック
            if (playerY < 60) { // 北境界
                const connection = areaConnections[gameState.currentArea];
                if (connection.north !== undefined) {
                    document.getElementById('boundaryNorth').classList.add('visible');
                }
            }
            if (playerY > containerRect.height - 60) { // 南境界
                const connection = areaConnections[gameState.currentArea];
                if (connection.south !== undefined) {
                    document.getElementById('boundarySouth').classList.add('visible');
                }
            }
            if (playerX > containerRect.width - 60) { // 東境界
                const connection = areaConnections[gameState.currentArea];
                if (connection.east !== undefined) {
                    document.getElementById('boundaryEast').classList.add('visible');
                }
            }
            if (playerX < 60) { // 西境界
                const connection = areaConnections[gameState.currentArea];
                if (connection.west !== undefined) {
                    document.getElementById('boundaryWest').classList.add('visible');
                }
            }
        }

        // エリア移動ダイアログ表示
        function showMoveDialog(direction) {
            const connection = areaConnections[gameState.currentArea];
            const targetArea = connection[direction];

            if (targetArea === undefined) return;

            gameState.pendingAreaMove = targetArea;
            const dialog = document.getElementById('moveDialog');
            const message = document.getElementById('moveMessage');

            message.textContent = `エリア ${areaNames[targetArea]} に移動しますか？`;
            dialog.style.display = 'block';
        }

        // エリア移動実行
        function executeAreaMove() {
            if (gameState.pendingAreaMove === null) return;

            gameState.currentArea = gameState.pendingAreaMove;
            gameState.pendingAreaMove = null;

            // 新エリアでの開始位置を設定
            const container = document.querySelector('.current-area');
            const containerRect = container.getBoundingClientRect();
            gameState.playerPosition = {
                x: containerRect.width / 2,
                y: containerRect.height / 2
            };

            // 敵位置をランダムに設定
            gameState.enemyPosition = {
                x: Math.random() * (containerRect.width - 100) + 50,
                y: Math.random() * (containerRect.height - 100) + 50
            };

            // UI更新
            document.getElementById('areaInfo').textContent = `エリア ${areaNames[gameState.currentArea]}`;
            updateShipPosition(document.getElementById('playerShip'), gameState.playerPosition);
            updateShipPosition(document.getElementById('enemyShip'), gameState.enemyPosition);
            updateDetectionRange();
            checkDetection();
            updateStatus();
            checkAreaBoundary();

            // ダイアログを閉じる
            document.getElementById('moveDialog').style.display = 'none';
        }

        // 艦船位置更新
        function updateShipPosition(ship, position) {
            ship.style.left = position.x - 10 + 'px';
            ship.style.top = position.y - 15 + 'px';
        }

        // 探知範囲表示更新
        function updateDetectionRange() {
            const range = document.getElementById('detectionRange');
            const sensorRanges = {
                optical: 80,
                thermal: 150,
                em: 250,
                dark: 200
            };

            const baseRange = sensorRanges[gameState.activeSensor];
            const actualRange = baseRange * (gameState.sensorPower / 100);

            range.style.width = actualRange * 2 + 'px';
            range.style.height = actualRange * 2 + 'px';
            range.style.left = (gameState.playerPosition.x - actualRange) + 'px';
            range.style.top = (gameState.playerPosition.y - actualRange) + 'px';
        }

        // 探知判定
        function checkDetection() {
            const distance = Math.sqrt(
                Math.pow(gameState.playerPosition.x - gameState.enemyPosition.x, 2) +
                Math.pow(gameState.playerPosition.y - gameState.enemyPosition.y, 2)
            );

            const sensorRanges = {
                optical: 80,
                thermal: 150,
                em: 250,
                dark: 200
            };

            const detectionRange = sensorRanges[gameState.activeSensor] * (gameState.sensorPower / 100);

            if (distance <= detectionRange) {
                gameState.detectionStatus = `敵艦探知: ${Math.round(distance)}m`;
                document.getElementById('enemyShip').style.opacity = '0.8';
            } else {
                gameState.detectionStatus = null;
                document.getElementById('enemyShip').style.opacity = '0.3';
            }
        }

        // ステータス表示更新
        function updateStatus() {
            const heatLevel = gameState.generatorPower > 70 ? '高' : gameState.generatorPower > 40 ? '中' : '低';
            const emLevel = gameState.aiPower > 70 ? '高' : gameState.aiPower > 40 ? '中' : '低';
            const moveStatus = gameState.isMoving ? '移動中' : '停止';

            const status = `
                現在エリア: ${areaNames[gameState.currentArea]}<br>
                移動状態: ${moveStatus}<br>
                熱源発生: ${heatLevel}<br>
                電磁波発生: ${emLevel}<br>
                探知状況: ${gameState.detectionStatus || 'なし'}
            `;

            document.getElementById('statusDisplay').innerHTML = status;
        }

        // エリア内移動処理
        function moveToPosition(x, y) {
            if (gameState.isMoving) return;

            gameState.isMoving = true;
            const destination = document.getElementById('moveDestination');

            destination.style.left = x - 5 + 'px';
            destination.style.top = y - 5 + 'px';
            destination.style.display = 'block';

            // 移動時間計算
            const distance = Math.sqrt(
                Math.pow(x - gameState.playerPosition.x, 2) +
                Math.pow(y - gameState.playerPosition.y, 2)
            );
            const moveTime = (distance / gameState.moveSpeed) * 50;

            setTimeout(() => {
                gameState.playerPosition.x = x;
                gameState.playerPosition.y = y;

                updateShipPosition(document.getElementById('playerShip'), gameState.playerPosition);
                updateDetectionRange();
                checkDetection();
                updateStatus();
                checkAreaBoundary();

                gameState.isMoving = false;
                destination.style.display = 'none';
            }, moveTime);
        }

        // 初期化
        function init() {
            const playerShip = document.getElementById('playerShip');
            const enemyShip = document.getElementById('enemyShip');
            const container = document.querySelector('.current-area');

            // 初期位置設定
            updateShipPosition(playerShip, gameState.playerPosition);
            updateShipPosition(enemyShip, gameState.enemyPosition);
            updateDetectionRange();
            updateStatus();
            checkAreaBoundary();

            // エリアクリックイベント
            container.addEventListener('click', (e) => {
                if (e.target.classList.contains('area-boundary')) return;

                const rect = container.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;
                moveToPosition(x, y);
            });

            // 境界クリックイベント
            document.querySelectorAll('.area-boundary').forEach(boundary => {
                boundary.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const direction = boundary.dataset.direction;
                    showMoveDialog(direction);
                });
            });

            // ダイアログボタンイベント
            document.getElementById('confirmMove').addEventListener('click', executeAreaMove);
            document.getElementById('cancelMove').addEventListener('click', () => {
                document.getElementById('moveDialog').style.display = 'none';
                gameState.pendingAreaMove = null;
            });

            // スライダーイベント
            document.getElementById('generatorSlider').addEventListener('input', (e) => {
                gameState.generatorPower = parseInt(e.target.value);
                document.getElementById('generatorValue').textContent = gameState.generatorPower + '%';
                checkDetection();
                updateStatus();
            });

            document.getElementById('aiSlider').addEventListener('input', (e) => {
                gameState.aiPower = parseInt(e.target.value);
                document.getElementById('aiValue').textContent = gameState.aiPower + '%';
                updateStatus();
            });

            document.getElementById('speedSlider').addEventListener('input', (e) => {
                gameState.moveSpeed = parseInt(e.target.value);
                document.getElementById('speedValue').textContent = gameState.moveSpeed + '%';
            });

            document.getElementById('sensorPowerSlider').addEventListener('input', (e) => {
                gameState.sensorPower = parseInt(e.target.value);
                document.getElementById('sensorPowerValue').textContent = gameState.sensorPower + '%';
                updateDetectionRange();
                checkDetection();
                updateStatus();
            });

            // センサーボタンイベント
            document.querySelectorAll('.sensor-btn').forEach(btn => {
                btn.addEventListener('click', () => {
                    document.querySelectorAll('.sensor-btn').forEach(b => b.classList.remove('active'));
                    btn.classList.add('active');

                    const sensorMap = {
                        'opticalSensor': 'optical',
                        'thermalSensor': 'thermal',
                        'emSensor': 'em',
                        'darkSensor': 'dark'
                    };

                    gameState.activeSensor = sensorMap[btn.id];
                    updateDetectionRange();
                    checkDetection();
                    updateStatus();
                });
            });
        }

        // ページ読み込み後に初期化
        window.addEventListener('load', init);
    </script>
</body>
</html>


