    <script>
        // ゲーム状態
        const gameState = {
            currentArea: 0, // 0:A-1, 1:A-2, 2:B-1, 3:B-2
            // バーチャルエリア内での絶対座標
            playerPosition: { x: 5000, y: 5000 }, // エリア中央
            enemyPosition: { x: 6000, y: 6000 },
            // 視点座標（バーチャルエリアのオフセット）
            viewOffset: { x: -4500, y: -4500 },
            // ズーム
            zoomLevel: 1.0,
            // 移動関連
            isMoving: false,
            moveTarget: null,
            moveStartTime: null,
            moveStartPos: null,
            moveDuration: 0,
            speedMultiplier: 1.0, // 速度倍率（低速:0.3, 中速:1.0, 高速:3.0）
            // ドラッグ関連
            isDragging: false,
            dragStart: { x: 0, y: 0 },
            dragStartOffset: { x: 0, y: 0 },
            // センサー等
            activeSensor: 'optical',
            generatorPower: 50,
            aiPower: 50,
            sensorPower: 40,
            detectionStatus: null,
            pendingAreaMove: null
        };

        const areaNames = ['A-1', 'A-2', 'B-1', 'B-2'];
        const areaConnections = {
            0: { north: 1, east: 2 },      // A-1 -> A-2(北), B-1(東)
            1: { south: 0, east: 3 },      // A-2 -> A-1(南), B-2(東)
            2: { north: 3, west: 0 },      // B-1 -> B-2(北), A-1(西)
            3: { south: 2, west: 1 }       // B-2 -> B-1(南), A-2(西)
        };

        // ドラッグスクロール
        function initDragScroll() {
            const viewport = document.getElementById('viewport');

            viewport.addEventListener('mousedown', startDrag);
            viewport.addEventListener('mousemove', drag);
            viewport.addEventListener('mouseup', endDrag);
            viewport.addEventListener('mouseleave', endDrag);

            // タッチイベント
            viewport.addEventListener('touchstart', (e) => {
                e.preventDefault();
                const touch = e.touches[0];
                startDrag({clientX: touch.clientX, clientY: touch.clientY});
            });

            viewport.addEventListener('touchmove', (e) => {
                e.preventDefault();
                const touch = e.touches[0];
                drag({clientX: touch.clientX, clientY: touch.clientY});
            });

            viewport.addEventListener('touchend', (e) => {
                e.preventDefault();
                endDrag();
            });
        }

        function startDrag(e) {
            if (e.target.classList.contains('ship') || e.target.classList.contains('area-boundary-zone')) {
                return;
            }

            gameState.isDragging = true;
            gameState.dragStart = { x: e.clientX, y: e.clientY };
            gameState.dragStartOffset = { ...gameState.viewOffset };
            document.getElementById('viewport').classList.add('dragging');
        }

        function drag(e) {
            if (!gameState.isDragging) return;

            const deltaX = e.clientX - gameState.dragStart.x;
            const deltaY = e.clientY - gameState.dragStart.y;

            gameState.viewOffset.x = gameState.dragStartOffset.x + deltaX;
            gameState.viewOffset.y = gameState.dragStartOffset.y + deltaY;

            updateViewport();
        }

        function endDrag() {
            gameState.isDragging = false;
            document.getElementById('viewport').classList.remove('dragging');
        }

        // 視点更新
        function updateViewport() {
            const virtualArea = document.getElementById('virtualArea');
            virtualArea.style.left = gameState.viewOffset.x + 'px';
            virtualArea.style.top = gameState.viewOffset.y + 'px';
            virtualArea.style.transform = `scale(${gameState.zoomLevel})`;
            virtualArea.style.transformOrigin = '0 0';

            updateViewportInfo();
            checkAreaBoundary();
        }

        function updateViewportInfo() {
            const info = document.getElementById('viewportInfo');
            info.textContent = `座標: ${Math.round(-gameState.viewOffset.x)}, ${Math.round(-gameState.viewOffset.y)} | ズーム: ${Math.round(gameState.zoomLevel * 100)}%`;
        }

        // ズーム機能
        function zoomIn() {
            gameState.zoomLevel = Math.min(gameState.zoomLevel * 1.2, 3.0);
            updateViewport();
            updateZoomDisplay();
        }

        function zoomOut() {
            gameState.zoomLevel = Math.max(gameState.zoomLevel / 1.2, 0.3);
            updateViewport();
            updateZoomDisplay();
        }

        function updateZoomDisplay() {
            document.getElementById('zoomLevel').textContent = Math.round(gameState.zoomLevel * 100) + '%';
        }

        // 速度制御
        function setSpeedMultiplier(multiplier, buttonId) {
            gameState.speedMultiplier = multiplier;

            // アクティブボタンの切り替え
            document.querySelectorAll('.speed-btn').forEach(btn => btn.classList.remove('active'));
            document.getElementById(buttonId).classList.add('active');

            // 移動中なら速度を再計算
            if (gameState.isMoving) {
                calculateMoveDuration();
            }
        }

        // 艦船移動処理（ゆっくり移動）
        function moveToPosition(worldX, worldY) {
            if (gameState.isMoving) {
                // 移動中の場合は目的地を変更
                gameState.moveTarget = { x: worldX, y: worldY };
                showMoveDestination();
                calculateMoveDuration();
                return;
            }

            gameState.isMoving = true;
            gameState.moveTarget = { x: worldX, y: worldY };
            gameState.moveStartTime = Date.now();
            gameState.moveStartPos = { ...gameState.playerPosition };

            showMoveDestination();
            calculateMoveDuration();

            document.getElementById('moveCancelBtn').style.display = 'block';

            // 移動アニメーション開始
            requestAnimationFrame(updateMovement);
        }

        function calculateMoveDuration() {
            const distance = Math.sqrt(
                Math.pow(gameState.moveTarget.x - gameState.playerPosition.x, 2) +
                Math.pow(gameState.moveTarget.y - gameState.playerPosition.y, 2)
            );

            // ジェネレーター出力に基づく速度計算（出力が低いほど遅い）
            const speed = Math.max(gameState.generatorPower, 5); // 最低速度保証を下げる
            let baseDuration = (distance / speed) * 500; // 基本速度係数

            // 速度倍率を適用
            baseDuration = baseDuration / gameState.speedMultiplier;

            // 最低移動時間を2秒、最大60秒に設定
            gameState.moveDuration = Math.max(2000, Math.min(baseDuration, 60000));
        }

        function updateMovement() {
            if (!gameState.isMoving || !gameState.moveTarget) return;

            const elapsed = Date.now() - gameState.moveStartTime;
            const progress = Math.min(elapsed / gameState.moveDuration, 1);

            // イージング関数（滑らかな移動）
            const easeProgress = 1 - Math.pow(1 - progress, 3);

            gameState.playerPosition.x = gameState.moveStartPos.x + 
                (gameState.moveTarget.x - gameState.moveStartPos.x) * easeProgress;
            gameState.playerPosition.y = gameState.moveStartPos.y + 
                (gameState.moveTarget.y - gameState.moveStartPos.y) * easeProgress;

            updateShipPosition();
            updateDetectionRange();
            checkDetection();
            updateStatus();

            if (progress >= 1) {
                // 移動完了
                gameState.isMoving = false;
                gameState.moveTarget = null;
                document.getElementById('moveCancelBtn').style.display = 'none';
                document.getElementById('moveDestination').style.display = 'none';
                document.getElementById('movePath').style.display = 'none';
            } else {
                requestAnimationFrame(updateMovement);
            }
        }

        function cancelMovement() {
            gameState.isMoving = false;
            gameState.moveTarget = null;
            document.getElementById('moveCancelBtn').style.display = 'none';
            document.getElementById('moveDestination').style.display = 'none';
            document.getElementById('movePath').style.display = 'none';
        }

        function showMoveDestination() {
            const destination = document.getElementById('moveDestination');
            destination.style.left = gameState.moveTarget.x - 5 + 'px';
            destination.style.top = gameState.moveTarget.y - 5 + 'px';
            destination.style.display = 'block';

            // 移動経路を表示
            const path = document.getElementById('movePath');
            const deltaX = gameState.moveTarget.x - gameState.playerPosition.x;
            const deltaY = gameState.moveTarget.y - gameState.playerPosition.y;
            const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);
            const angle = Math.atan2(deltaY, deltaX) * 180 / Math.PI;

            path.style.width = distance + 'px';
            path.style.height = '0px';
            path.style.left = gameState.playerPosition.x + 'px';
            path.style.top = gameState.playerPosition.y + 'px';
            path.style.transform = `rotate(${angle}deg)`;
            path.style.transformOrigin = '0 0';
            path.style.display = 'block';
        }

        // 艦船位置更新
        function updateShipPosition() {
            const playerShip = document.getElementById('playerShip');
            const enemyShip = document.getElementById('enemyShip');

            playerShip.style.left = gameState.playerPosition.x - 10 + 'px';
            playerShip.style.top = gameState.playerPosition.y - 15 + 'px';

            enemyShip.style.left = gameState.enemyPosition.x - 10 + 'px';
            enemyShip.style.top = gameState.enemyPosition.y - 15 + 'px';
        }

        // 探知範囲表示更新
        function updateDetectionRange() {
            const range = document.getElementById('detectionRange');
            const sensorRanges = {
                optical: 120,
                thermal: 200,
                em: 350,
                dark: 280
            };

            const baseRange = sensorRanges[gameState.activeSensor];
            const actualRange = baseRange * (gameState.sensorPower / 100);

            range.style.width = actualRange * 2 + 'px';
            range.style.height = actualRange * 2 + 'px';
            range.style.left = (gameState.playerPosition.x - actualRange) + 'px';
            range.style.top = (gameState.playerPosition.y - actualRange) + 'px';
        }

        // 探知判定
        function checkDetection() {
            const distance = Math.sqrt(
                Math.pow(gameState.playerPosition.x - gameState.enemyPosition.x, 2) +
                Math.pow(gameState.playerPosition.y - gameState.enemyPosition.y, 2)
            );

            const sensorRanges = {
                optical: 120,
                thermal: 200,
                em: 350,
                dark: 280
            };

            const detectionRange = sensorRanges[gameState.activeSensor] * (gameState.sensorPower / 100);

            if (distance <= detectionRange) {
                gameState.detectionStatus = `敵艦探知: ${Math.round(distance)}m`;
                document.getElementById('enemyShip').style.opacity = '0.8';
            } else {
                gameState.detectionStatus = null;
                document.getElementById('enemyShip').style.opacity = '0.3';
            }
        }

        // エリア境界チェック
        function checkAreaBoundary() {
            const boundaries = document.querySelectorAll('.area-boundary-zone');
            const playerX = gameState.playerPosition.x;
            const playerY = gameState.playerPosition.y;

            // バーチャルエリアのサイズ（1000vw x 1000vh相当）
            const areaWidth = window.innerWidth * 10;
            const areaHeight = window.innerHeight * 10;

            boundaries.forEach(boundary => {
                boundary.classList.remove('visible');
            });

            // 境界近接チェック（エリア端から200px以内）
            if (playerY < 200) { // 北境界
                const connection = areaConnections[gameState.currentArea];
                if (connection.north !== undefined) {
                    document.getElementById('boundaryNorth').classList.add('visible');
                }
            }
            if (playerY > areaHeight - 200) { // 南境界
                const connection = areaConnections[gameState.currentArea];
                if (connection.south !== undefined) {
                    document.getElementById('boundarySouth').classList.add('visible');
                }
            }
            if (playerX > areaWidth - 200) { // 東境界
                const connection = areaConnections[gameState.currentArea];
                if (connection.east !== undefined) {
                    document.getElementById('boundaryEast').classList.add('visible');
                }
            }
            if (playerX < 200) { // 西境界
                const connection = areaConnections[gameState.currentArea];
                if (connection.west !== undefined) {
                    document.getElementById('boundaryWest').classList.add('visible');
                }
            }
        }

        // エリア移動ダイアログ表示
        function showMoveDialog(direction) {
            const connection = areaConnections[gameState.currentArea];
            const targetArea = connection[direction];

            if (targetArea === undefined) return;

            gameState.pendingAreaMove = targetArea;
            const dialog = document.getElementById('moveDialog');
            const message = document.getElementById('moveMessage');

            message.textContent = `エリア ${areaNames[targetArea]} に移動しますか？`;
            dialog.style.display = 'block';
        }

        // エリア移動実行
        function executeAreaMove() {
            if (gameState.pendingAreaMove === null) return;

            gameState.currentArea = gameState.pendingAreaMove;
            gameState.pendingAreaMove = null;

            // 新エリアでのプレイヤー開始位置を設定（エリア中央）
            const areaWidth = window.innerWidth * 10;
            const areaHeight = window.innerHeight * 10;
            gameState.playerPosition = {
                x: areaWidth / 2,
                y: areaHeight / 2
            };

            // 敵位置をランダムに設定
            gameState.enemyPosition = {
                x: Math.random() * (areaWidth - 1000) + 500,
                y: Math.random() * (areaHeight - 1000) + 500
            };

            // 視点をプレイヤー中心に調整（画面中央に表示）
            gameState.viewOffset = {
                x: -(gameState.playerPosition.x - window.innerWidth / 2),
                y: -(gameState.playerPosition.y - window.innerHeight / 2)
            };

            // UI更新
            document.getElementById('areaInfo').textContent = `エリア ${areaNames[gameState.currentArea]}`;
            updateShipPosition();
            updateViewport();
            updateDetectionRange();
            checkDetection();
            updateStatus();

            // ダイアログを閉じる
            document.getElementById('moveDialog').style.display = 'none';
        }

        // ステータス表示更新
        function updateStatus() {
            const heatLevel = gameState.generatorPower > 70 ? '高' : gameState.generatorPower > 40 ? '中' : '低';
            const emLevel = gameState.aiPower > 70 ? '高' : gameState.aiPower > 40 ? '中' : '低';
            const moveStatus = gameState.isMoving ? '移動中' : '停止';

            const status = `
                現在エリア: ${areaNames[gameState.currentArea]}<br>
                移動状態: ${moveStatus}<br>
                熱源発生: ${heatLevel}<br>
                電磁波発生: ${emLevel}<br>
                探知状況: ${gameState.detectionStatus || 'なし'}
            `;

            document.getElementById('statusDisplay').innerHTML = status;
        }

        // ワールド座標変換（クリック位置→バーチャルエリア座標）
        function screenToWorld(screenX, screenY) {
            return {
                x: screenX - gameState.viewOffset.x,
                y: screenY - gameState.viewOffset.y
            };
        }

        // 初期化
        function init() {
            // ドラッグスクロール初期化
            initDragScroll();

            // マウスホイールでズーム
            document.getElementById('viewport').addEventListener('wheel', (e) => {
                e.preventDefault();
                if (e.deltaY < 0) {
                    zoomIn();
                } else {
                    zoomOut();
                }
            });

            // 初期位置設定
            updateShipPosition();
            updateViewport();
            updateDetectionRange();
            updateStatus();
            updateZoomDisplay();

            // エリアクリックイベント（移動指示）
            document.getElementById('virtualArea').addEventListener('click', (e) => {
                if (gameState.isDragging) return;
                if (e.target.classList.contains('area-boundary-zone')) return;

                const virtualArea = document.getElementById('virtualArea');
                const rect = virtualArea.getBoundingClientRect();
                // ズームレベルを考慮した座標変換
                const worldX = (e.clientX - rect.left) / gameState.zoomLevel;
                const worldY = (e.clientY - rect.top) / gameState.zoomLevel;
                moveToPosition(worldX, worldY);
            });

            // 境界クリックイベント
            document.querySelectorAll('.area-boundary-zone').forEach(boundary => {
                boundary.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const direction = boundary.dataset.direction;
                    showMoveDialog(direction);
                });
            });

            // 移動キャンセルボタン
            document.getElementById('moveCancelBtn').addEventListener('click', cancelMovement);

            // 速度制御ボタン
            document.getElementById('speedSlow').addEventListener('click', () => setSpeedMultiplier(0.3, 'speedSlow'));
            document.getElementById('speedMedium').addEventListener('click', () => setSpeedMultiplier(1.0, 'speedMedium'));
            document.getElementById('speedFast').addEventListener('click', () => setSpeedMultiplier(3.0, 'speedFast'));

            // ズーム制御ボタン
            document.getElementById('zoomIn').addEventListener('click', zoomIn);
            document.getElementById('zoomOut').addEventListener('click', zoomOut);

            // ダイアログボタンイベント
            document.getElementById('confirmMove').addEventListener('click', executeAreaMove);
            document.getElementById('cancelMove').addEventListener('click', () => {
                document.getElementById('moveDialog').style.display = 'none';
                gameState.pendingAreaMove = null;
            });

            // スライダーイベント
            document.getElementById('generatorSlider').addEventListener('input', (e) => {
                gameState.generatorPower = parseInt(e.target.value);
                document.getElementById('generatorValue').textContent = gameState.generatorPower + '%';
                if (gameState.isMoving) {
                    calculateMoveDuration(); // 移動中なら速度を再計算
                }
                checkDetection();
                updateStatus();
            });

            document.getElementById('aiSlider').addEventListener('input', (e) => {
                gameState.aiPower = parseInt(e.target.value);
                document.getElementById('aiValue').textContent = gameState.aiPower + '%';
                updateStatus();
            });

            document.getElementById('sensorPowerSlider').addEventListener('input', (e) => {
                gameState.sensorPower = parseInt(e.target.value);
                document.getElementById('sensorPowerValue').textContent = gameState.sensorPower + '%';
                updateDetectionRange();
                checkDetection();
                updateStatus();
            });

            // センサーボタンイベント
            document.querySelectorAll('.sensor-btn').forEach(btn => {
                btn.addEventListener('click', () => {
                    document.querySelectorAll('.sensor-btn').forEach(b => b.classList.remove('active'));
                    btn.classList.add('active');

                    const sensorMap = {
                        'opticalSensor': 'optical',
                        'thermalSensor': 'thermal',
                        'emSensor': 'em',
                        'darkSensor': 'dark'
                    };

                    gameState.activeSensor = sensorMap[btn.id];
                    updateDetectionRange();
                    checkDetection();
                    updateStatus();
                });
            });
        }

        // ページ読み込み後に初期化
        window.addEventListener('load', init);
    </script>
</body>
</html>


