<!DOCTYPE html>
<html lang='ja'>
<head>
    <meta charset='UTF-8'>
    <meta name='viewport' content='width=device-width, initial-scale=1.0'>
    <title>Dark Echo - Prototype v0.1</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            background: #0a0a0a;
            color: #00ff00;
            font-family: 'Courier New', monospace;
            overflow: hidden;
        }

        .game-container {
            display: flex;
            flex-direction: column;
            height: 100vh;
        }

        .map-area {
            height: 60%;
            position: relative;
            background: linear-gradient(45deg, #111, #000);
        }

        .control-panel {
            height: 40%;
            background: #1a1a1a;
            border-top: 2px solid #00ff00;
            padding: 8px;
            overflow-y: auto;
            display: grid;
            grid-template-columns: 1fr 1fr;
            grid-template-rows: 1fr 1fr;
            gap: 8px;
        }

        .grid-container {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            overflow: hidden;
            cursor: grab;
        }

        .grid-container.dragging {
            cursor: grabbing;
        }

        .virtual-area {
            position: absolute;
            width: 1000vw; /* 画面幅の10倍 */
            height: 1000vh; /* 画面高さの10倍 */
            background: 
                radial-gradient(circle at 20% 30%, rgba(0, 255, 0, 0.05) 0%, transparent 20%),
                radial-gradient(circle at 80% 70%, rgba(0, 255, 0, 0.03) 0%, transparent 25%),
                linear-gradient(45deg, rgba(0, 255, 0, 0.02) 0%, rgba(0, 0, 0, 0.8) 100%);
            border: 5px solid #00ff00;
            top: -450vh; /* 中央に配置 */
            left: -450vw; /* 中央に配置 */
        }

        .area-info {
            position: fixed;
            top: 60px;
            left: 20px;
            font-size: 14px;
            color: #00ff00;
            opacity: 0.8;
            z-index: 100;
            background: rgba(0, 0, 0, 0.7);
            padding: 5px 10px;
            border-radius: 5px;
        }

        .viewport-info {
            position: fixed;
            top: 90px;
            left: 20px;
            font-size: 10px;
            color: #ffff00;
            opacity: 0.6;
            z-index: 100;
            background: rgba(0, 0, 0, 0.7);
            padding: 3px 8px;
            border-radius: 3px;
        }

        .move-path {
            position: absolute;
            border: 2px dashed #ffff00;
            opacity: 0.7;
            pointer-events: none;
            z-index: 5;
        }

        .move-controls {
            position: fixed;
            bottom: 120px;
            right: 20px;
            z-index: 100;
        }

        .move-cancel-btn {
            background: #ff3333;
            border: 1px solid #ff6666;
            color: white;
            padding: 8px 12px;
            border-radius: 5px;
            cursor: pointer;
            font-size: 10px;
            margin-bottom: 5px;
            display: none;
        }

        .move-cancel-btn:hover {
            background: #ff6666;
        }

        .speed-control {
            position: fixed;
            top: 120px;
            left: 20px;
            z-index: 100;
            background: rgba(0, 0, 0, 0.7);
            padding: 8px;
            border-radius: 5px;
            border: 1px solid #00ff00;
        }

        .speed-toggle {
            display: flex;
            gap: 5px;
            margin-bottom: 5px;
        }

        .speed-btn {
            background: #333;
